#!/usr/bin/env bash
# Starts chaekcheck on the server with its secret values (cycle 17, plan ADR-0103, ADR-0104, design-delta "띄우기").
#
#   up.sh [service ...]      run in any folder; extra arguments go to `docker compose up -d` (e.g. up.sh backend)
#
# 1. secrets.env next to compose.yaml without the "generated by up.sh" first line was put there by hand (laptop, no
#    IAM role): it is used as it is and Parameter Store is not read.
# 2. Otherwise every parameter under /chaekcheck/prod/ is read once with the EC2 instance role (no access keys).
#    The last part of the name is the variable name (/chaekcheck/prod/DB_PASSWORD -> DB_PASSWORD); compose.yaml maps
#    them to what each container reads. When reading fails or a required name is missing, the script stops before
#    writing anything and the running containers stay as they are.
# 3. The values go to secrets.env (chmod 600, written to a temporary file first and then moved), and compose starts
#    with --env-file secrets.env, plus --env-file prod.env when that file exists (settings that are not secret).
#
# Needs the AWS CLI on the server and a role allowed ssm:GetParametersByPath on /chaekcheck/prod/* (plus kms:Decrypt
# on the aws/ssm key for SecureString values).
set -euo pipefail

PARAM_PATH="${CHAEKCHECK_PARAM_PATH:-/chaekcheck/prod/}"
REGION="${AWS_REGION:-ap-southeast-2}"
# Names that must be in Parameter Store before anything starts (plan 17, user decision 2026-10-18: Webshare user and
# password are the main way, IP Authorization the fallback; TUNNEL_TOKEN for cloudflared; the Kakao login keys and the
# JWT signing key, login being on from the opening). Also read when present: WEBSHARE_API_KEY.
# TODO(확인 필요): add CHAEKCHECK_PICKS_NLK_API_KEY when the picks fetch is turned on.
REQUIRED="${CHAEKCHECK_REQUIRED_PARAMS:-DB_PASSWORD WEBSHARE_PROXIES WEBSHARE_PROXY_USERNAME WEBSHARE_PROXY_PASSWORD TUNNEL_TOKEN KAKAO_REST_API_KEY KAKAO_CLIENT_SECRET KAKAO_ADMIN_KEY KAKAO_APP_ID AUTH_JWT_SECRET}"
MARKER="# generated by up.sh from Parameter Store; do not edit, run up.sh again"

DIR="${CHAEKCHECK_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
SECRETS="$DIR/secrets.env"
cd "$DIR"

fail() {
	echo "up.sh: $*; nothing written, running containers left as they are" >&2
	exit 1
}

if [[ -f "$SECRETS" ]] && [[ "$(head -n 1 "$SECRETS")" != "$MARKER" ]]; then
	echo "up.sh: using $SECRETS as it is (put there by hand)"
else
	command -v aws >/dev/null || fail "the AWS CLI is not installed"
	raw="$(mktemp)"
	trap 'rm -f "$raw"' EXIT
	# JSON, so values with tabs or spaces stay whole; the CLI follows the pages by itself.
	aws ssm get-parameters-by-path --region "$REGION" --path "$PARAM_PATH" --recursive --with-decryption \
		--query 'Parameters[].{n:Name,v:Value}' --output json >"$raw" \
		|| fail "reading $PARAM_PATH failed (role, network or path)"

	umask 077
	next="$(mktemp "$DIR/.secrets.env.XXXXXX")"
	trap 'rm -f "$raw" "$next"' EXIT
	python3 - "$raw" "$PARAM_PATH" "$REQUIRED" "$MARKER" >"$next" <<'PY' || fail "the parameters could not be used"
import json, re, sys

raw, path, required, marker = sys.argv[1], sys.argv[2], sys.argv[3].split(), sys.argv[4]
values = {}
for p in json.load(open(raw)):
    name = p["n"][len(path):] if p["n"].startswith(path) else p["n"]
    if not re.fullmatch(r"[A-Z][A-Z0-9_]*", name):
        sys.exit(f"up.sh: parameter {p['n']} is not a variable name (A-Z, 0-9, _)")
    value = p["v"]
    # compose reads single-quoted values literally; a quote or a line break inside cannot be written that way
    if "'" in value or "\n" in value or "\r" in value:
        sys.exit(f"up.sh: parameter {name} has a quote or a line break")
    values[name] = value
missing = [n for n in required if not values.get(n, "").strip()]
if missing:
    sys.exit("up.sh: missing in Parameter Store: " + ", ".join(missing))
print(marker)
for name in sorted(values):
    print(f"{name}='{values[name]}'")
print(f"up.sh: {len(values)} values from {path}", file=sys.stderr)
PY
	chmod 600 "$next"
	mv -f "$next" "$SECRETS"
fi

env_files=(--env-file "$SECRETS")
[[ -f "$DIR/prod.env" ]] && env_files+=(--env-file "$DIR/prod.env")
exec docker compose "${env_files[@]}" up -d "$@"
